src/Etch.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Exercises the `vm.etch` cheatcode: it installs the RUNTIME bytecode
/// of `Impl` onto a bare address that was never deployed, then makes a real
/// external call into that address. The debugger must (a) render the `vm.etch`
/// call itself as a cheatcode frame (4a) and (b) — the point of 4b — resolve the
/// subsequent CALL frame at the etched address against the ETCHED code (Impl),
/// mapping it to Impl's source, WITHOUT corrupting the parent `run` frame.
interface Vm {
    function etch(address who, bytes calldata code) external;
}

/// The implementation whose runtime code is etched onto `TARGET`. Compiled in
/// the same unit as `Etch`, so its CBOR metadata is identifiable from build-info.
contract Impl {
    uint256 public stored;

    function setStored(uint256 v) external returns (uint256) {
        stored = v * 2; // the etched frame executes here → 21*2 = 42
        return stored;
    }
}

contract Etch {
    Vm constant vm = Vm(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D);

    /// A bare address (never deployed) that receives Impl's code via etch.
    address constant TARGET = address(uint160(0xBEEF));

    uint256 public result; // slot 0 — should hold 42 after run()

    function run() external {
        vm.etch(TARGET, type(Impl).runtimeCode); // TARGET.code = Impl runtime
        result = Impl(TARGET).setStored(21); // step INTO etched code → 42
    }
}

src/EtchRaw.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Exercises `vm.etch` with RAW bytecode that is NOT any compiled
/// contract — there is no CBOR metadata and no matching compilation unit, so
/// the debugger cannot identify a source for the etched frame. 4b must degrade
/// such a frame to EVM-only (disassembly / raw stepping) WITHOUT mis-resolving
/// its PCs against the caller's source map and WITHOUT corrupting the parent
/// `run` frame's stepping.
interface Vm {
    function etch(address who, bytes calldata code) external;
}

contract EtchRaw {
    Vm constant vm = Vm(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D);
    address constant TARGET = address(uint160(0xBEEF));

    bytes32 public out; // slot 0

    function run() external {
        // Minimal valid runtime: PUSH1 1; PUSH1 0; MSTORE; PUSH1 32; PUSH1 0;
        // RETURN → returns the 32-byte word 0x…01. No CBOR, not a known CU.
        vm.etch(TARGET, hex"600160005260206000f3");
        (bool ok, bytes memory ret) = TARGET.call("");
        require(ok, "raw call failed");
        out = abi.decode(ret, (bytes32)); // expect 0x…01
    }
}

src/FixedArrays.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Exercises FIXED-size arrays (`T[N]`) in both storage and memory,
/// with full-slot (uint256) elements so no packing is involved.
///
/// Storage layout: `fixedArr` occupies slots 0,1,2 inline (no length prefix,
/// no keccak); `sum` is slot 3. A memory `uint256[3]` local is stored inline
/// with no length word — element i at base + i*32.
contract FixedArrays {
    uint256[3] public fixedArr; // slots 0,1,2 (inline)
    uint256 public sum; // slot 3

    function fill() external {
        fixedArr[0] = 111;
        fixedArr[1] = 222;
        fixedArr[2] = 333;

        uint256[3] memory local;
        local[0] = 11;
        local[1] = 22;
        local[2] = 33;

        // Use `local` so it stays live to a clean statement boundary and its
        // memory pointer is resolvable; writes a separate slot so `fixedArr`
        // keeps [111, 222, 333].
        sum = local[0] + local[1] + local[2];
    }
}

src/Forwarder.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {ICallee} from "./Caller.sol";

/// @notice An EXTERNAL call made from inside an INTERNAL function: while the
/// callee runs, the caller's EVM frame must still show its internal call chain
/// (go → _forward), so stepping in/out of the callee changes the stack by one
/// frame at a time.
contract Forwarder {
    uint256 public result;

    function go(address callee, uint256 x) public {
        uint256 r = _forward(callee, x);
        result = r;
    }

    function _forward(address callee, uint256 x) internal returns (uint256) {
        uint256 r = ICallee(callee).compute(x);
        return r + 1;
    }
}

src/InheritedUdvt.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice A user-defined VALUE type (`type ... is address`), like uniswap-v4's
/// `Currency`. A local of this type must be shown in the variables view with its
/// underlying (address) value, not treated as a reference type.
type Token is address;

/// @notice Base contract holding an internal function with UDVT locals. The
/// entry contract INHERITS it — so resolving the function's locals must look past
/// the derived contract's own members (a by-name lookup scoped to the derived
/// contract would miss it and show no locals at all).
contract TokenBase {
    Token public t0; // slot 0
    Token public t1; // slot 1

    function mint(uint256 seed) internal returns (Token) {
        // A state write so the call is not optimized away.
        t0 = Token.wrap(address(uint160(seed + 1)));
        return t0;
    }

    /// A recursive helper so solc does NOT inline it — the arguments are passed on
    /// the stack, which is what forces `setupTokens`'s value-type locals to be read
    /// by a last-use SWAP (move) rather than a DUP (copy). Takes the UNWRAPPED
    /// addresses so the call site reads each local through `Token.unwrap(...)` —
    /// exactly the uniswap-v4 `MockERC20(Currency.unwrap(_currencyA))` shape.
    function order(address x, address y, uint256 depth)
        internal
        pure
        returns (Token, Token)
    {
        if (depth > 0) return order(x, y, depth - 1);
        return x < y ? (Token.wrap(x), Token.wrap(y)) : (Token.wrap(y), Token.wrap(x));
    }

    /// The reproducer body: two UDVT locals assigned from calls, then read into a
    /// multi-arg call. Under `--via-ir` a value local's LAST use is a SWAP (move),
    /// which the DUP-only read anchor missed — so `_a`/`_b` were shown without a
    /// value even once located.
    function setupTokens() internal returns (Token a, Token b) {
        Token _a = mint(0x11); // UDVT local (base-contract function)
        Token _b = mint(0x22); // UDVT local
        // _a/_b read through Token.unwrap(...) as a last-use move (SWAP).
        (a, b) = order(Token.unwrap(_a), Token.unwrap(_b), 1);
    }
}

/// @notice Entry contract: `run()` calls the INHERITED `setupTokens()`.
contract InheritedUdvt is TokenBase {
    function run() external {
        setupTokens();
    }
}

src/MemRefs.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Dual-pipeline reproducer for MEMORY reference-type locals: a dynamic
/// value array (`uint256[]`), a `string`, and a fixed-size memory array
/// (`uint256[3]`). Recorded BOTH viaIR and legacy so the variables-view
/// rendering of memory references is proven on each pipeline — the per-pc
/// stack-provenance path (viaIR, reordered/reused slots) AND the legacy
/// frame-relative slot model.
///
/// The locals are passed into a RECURSIVE (non-inlined) `consume`, so each is a
/// genuine last-use stack read (a tagged Identifier read the provenance analyzer
/// can anchor) — mirroring BytesArray / MemStruct.
contract MemRefs {
    uint256 public out; // slot 0

    function consume(
        uint256[] memory nums,
        string memory label,
        uint256[3] memory fixed3,
        uint256 depth
    ) internal returns (uint256) {
        if (depth > 0) return consume(nums, label, fixed3, depth - 1);
        out = nums.length + bytes(label).length + fixed3[2];
        return out;
    }

    function run() external returns (uint256) {
        uint256[] memory nums = new uint256[](2);
        nums[0] = 11;
        nums[1] = 22;
        string memory label = "hi";
        uint256[3] memory fixed3 = [uint256(101), 202, 303];
        return consume(nums, label, fixed3, 1); // read here (last use) — must be visible
    }
}

src/MemStruct.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice viaIR reproducer for locating a MEMORY STRUCT local per-pc.
///
/// A `memory` struct local holds a memory offset in a stack slot; the debugger
/// reads the struct's fields from memory through that slot. Under `--via-ir` the
/// slot is scheduled per-instruction (and the struct is often materialised only
/// near its use), so the legacy frame-relative slot model can't find it — the
/// variable then shows no value even while it is live and in scope. The per-pc
/// stack-provenance analyzer locates the slot instead.
struct LiqParams {
    int24 tickLower;
    int24 tickUpper;
    int128 liquidityDelta;
    bytes32 salt;
}

contract MemStruct {
    uint256 public out; // slot 0

    /// Recursive so solc does NOT inline it — `p` is passed on the stack, which is
    /// what makes `run`'s struct local a genuine last-use stack read.
    function consume(LiqParams memory p, uint256 depth) internal returns (uint256) {
        if (depth > 0) return consume(p, depth - 1);
        out = uint256(int256(p.liquidityDelta));
        return out;
    }

    function run() external returns (uint256) {
        LiqParams memory params = LiqParams({
            tickLower: int24(-120),
            tickUpper: int24(120),
            liquidityDelta: int128(1000),
            salt: bytes32(uint256(7))
        });
        return consume(params, 1); // params read here (last use) — must be visible
    }
}

src/ModCall.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @notice A modifier that CALLS an internal function: while `_check` runs, the
/// stack is [_check, checked, run] — the suspended modifier stays beneath it.
/// `guard` then calls `_guard` as its first statement.
contract ModCall {
    uint256 public stored;

    function _check(uint256 x) internal pure returns (bool) {
        return x > 0;
    }

    modifier checked(uint256 x) {
        require(_check(x), "zero");
        _;
    }

    function run(uint256 x) external checked(x) guard returns (uint256) {
        stored = x;
        return x + 1;
    }

    /// A modifier whose first statement is a bare call: under viaIR its code up
    /// to the call maps to the modifier header, not to the statement.
    modifier guard() {
        _guard();
        _;
    }

    function _guard() internal view {
        require(stored < type(uint256).max, "full");
    }
}

src/Modifiers.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Exercises a MODIFIER for DAP stack reconstruction. Paused inside the
/// modifier body (pre-placeholder) the stack should show [onlyPositive, bump];
/// paused inside the function body (after `_;`) it should show [bump] with the
/// modifier suspended.
contract Modifiers {
    uint256 public stored;

    modifier onlyPositive(uint256 x) {
        uint256 doubled = x * 2; // modifier-body local, pre-placeholder
        require(doubled > 0, "not positive");
        _; // placeholder → runs the function body
    }

    function bump(uint256 x) public onlyPositive(x) returns (uint256 r) {
        r = x + 1; // function body (modifier suspended here)
        stored = r;
    }
}

src/MultiMod.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @notice A function with TWO modifiers, entered by an internal call and by an
/// external one. Step-into stops at each modifier invocation in the header
/// before entering that modifier, so every step-in pushes at most one frame.
contract MultiMod {
    bool private unlocked = true;
    uint256 public stored;

    modifier whenUnlocked() {
        require(unlocked, "locked");
        _;
    }

    modifier atLeast(uint256 x, uint256 min) {
        require(x >= min, "too small");
        _;
    }

    function run(uint256 x) external returns (uint256) {
        uint256 a = guarded(x);
        uint256 b = this.guarded(x + 1);
        return a + b;
    }

    function guarded(uint256 x) public whenUnlocked atLeast(x, 1) returns (uint256) {
        stored = x;
        return x + 1;
    }
}

src/NestedCalls.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Exercises MULTI-LEVEL internal calls for DAP stack reconstruction:
/// NESTED (outer → level1 → level2) and SEQUENTIAL (outer → level1, then, after
/// it returns, outer → leaf). Used to test the internal-frame pop/re-push path.
contract NestedCalls {
    uint256 public result;

    function outer(uint256 x) public returns (uint256) {
        uint256 a = level1(x); // nested: level1 calls level2
        uint256 b = leaf(x); // sequential: called after level1 returned
        result = a + b;
        return result;
    }

    function level1(uint256 y) internal returns (uint256) {
        uint256 inner = level2(y); // nested call
        return inner + 1;
    }

    function level2(uint256 z) internal returns (uint256) {
        return z * 2; // deepest frame
    }

    function leaf(uint256 w) internal returns (uint256) {
        return w + 100; // sequential sibling frame
    }
}

src/Prank.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Exercises the `vm.startPrank` cheatcode so we can see what
/// kontrol-node emits for `msg.sender` in the PRANKED callee frame.
///
/// `vm.startPrank(who)` changes the `msg.sender` observed by the *callee* of
/// each subsequent external call (not within the pranking frame itself). So
/// `Target.record()` — called after the prank — should observe `who` as its
/// `msg.sender`, and the trace's per-step `msgSender` inside Target's frame
/// should be `who`, not the Prank contract's address.
interface Vm {
    function startPrank(address who) external;
    function stopPrank() external;
}

contract Target {
    address public seen;

    function record() external returns (address) {
        seen = msg.sender; // should be the pranked address while pranking
        return seen;
    }
}

contract Prank {
    Vm constant vm = Vm(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D);

    address public seenBefore; // msg.sender at Target before the prank
    address public seenDuring; // msg.sender at Target during the prank

    function run(address who) external {
        Target target = new Target();

        seenBefore = target.record(); // no prank → should be this contract

        vm.startPrank(who);
        seenDuring = target.record(); // pranked → should be `who`
        vm.stopPrank();
    }
}

