src/RevertStep.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Regression fixture for the step-over `combinedDepth` DRIFT bug.
///
/// `run` has three statements; statement 2 makes an EXTERNAL call that REVERTS
/// (caught by try/catch). An external function is entered via a source-map
/// `jump:'i'`, but a revert exits WITHOUT the balancing `jump:'o'` epilogue — so
/// a single global jump-fold accumulator leaks +1 and never recovers, inflating
/// every later statement's combinedDepth. Step-over from statement 1 (which
/// stops at the first statement whose combinedDepth <= the origin's) then skips
/// statement 3 and runs to the terminal step. A per-EVM-frame fold discards the
/// reverted callee's imbalance on return, so stepping stays correct.
contract Reverter {
    function boom() external pure {
        revert("boom");
    }
}

contract RevertStep {
    uint256 public a; // slot 0
    uint256 public b; // slot 1

    function run(address r) external {
        a = 1; // statement 1 (step-over origin)
        try Reverter(r).boom() {} catch {} // statement 2: reverting external call
        b = 2; // statement 3 (step-over MUST land here, not the end)
    }
}

src/StepStress.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice LEGACY stepping stress. Sequential declarations, a `for` loop with a
/// back-edge, and a multi-argument internal call built from earlier locals —
/// the shapes that, under `--via-ir`, produce the out-of-order straight-line
/// SETUP artifacts the stepper suppresses via #persists / #isBackwardSetupArtifact.
///
/// Compiled LEGACY (no `--via-ir`), this fixture proves those viaIR-oriented
/// heuristics do NOT misfire on classic codegen: step-over must walk the
/// statements in SOURCE order (no false "backward fall-through" skip) and
/// step-into `combine` must land on its first line, not a later one.
contract StepStress {
    uint256 public out; // slot 0

    function combine(uint256 a, uint256 b, uint256 c) internal pure returns (uint256) {
        uint256 s = a + b; // first line of combine (step-into target)
        return s + c;
    }

    function run() external returns (uint256) {
        uint256 x = 1;
        uint256 y = 2;
        uint256 z = 3;
        uint256 sum = 0;
        for (uint256 i = 0; i < 3; i++) {
            sum += i; // loop body (back-edge to the header)
        }
        uint256 r = combine(x, y, z); // multi-arg call from earlier locals
        out = sum + r; // sum=3, r=6 → out=9
        return out;
    }
}

